def test_qubit_len(n):
    r = remote(HOST, PORT)
    try:
        welcome = r.recvuntil(b"qubits to communicate with?")
        r.sendline(str(n).encode())
        data = r.recv(timeout=4)
        r.close()
        return data.decode(errors='ignore')
    except Exception as e:
        r.close()
        return f"error({repr(e)})"

def main():
    start = 1
    stop = 150
    for n in range(start, stop+1):
        res = test_qubit_len(n)
        print(f"{n}: {repr(res)}")
        if 'error' in res.lower() or 'invalid' in res.lower() or 'too' in res.lower() or 'range' in res.lower():
            break

if __name__ == "__main__":
    main()

from pwn import remote
import sys
HOST = "misc.chal.csaw.io"
PORT = 5000

# Try single interaction, 512 and 1024 bases of 'X'
def try_big(n):
    r = remote(HOST, PORT)
    out = r.recvuntil(b"qubits to communicate with?")
    r.sendline(str(n).encode())
    see = r.recvline(timeout=5)
    # Most likely prompt for input bases
    if b'bases' in see or b'input' in see:
        r.sendline(b'X'*n)
        try:
            res = r.recvall(timeout=7)
        except Exception as e:
            res = b''
        print(f"{n} X's result: {repr(res)}")
    else:
        print(f"Unusual for n={n}: {see}")
    r.close()

for num in [128, 256, 512, 1024, 2048]:
    try:
        try_big(num)
    except Exception as e:
        print(f"Exception trying {num}: {e}")

